from pathlib import Path
HERE=Path(__file__).resolve().parent;WORK=HERE.parents[2];OUT=WORK/'amplifier-slots';R=json.loads((OUT/'Pure_GGS_Amplifier_Results.json').read_text());arms=R['arms'];B={(m['seed'],m['rotation']):m for m in R['reused_baseline_games']}
