for a in arms:
 b=a['baseline_recovery'];v=a['replacement_recovery'];lines.append(f"| {a['removed']} | {b['recovered']} / {b['events']} | {v['recovered']} / {v['events']} |")
lines+=['','Recovery retains the earlier definition: within three following Pure turns, another GGS-created Dragon plus at least half pre-wipe offensive power, minimum 5. Wipes require traced spell/ability loss of at least three creatures. Small denominators and game endings limit this estimate.','','Stall labels retain the prior operational classifier:1 mana/color;2 no fresh ammunition;3 access;4 continuation/readiness;5 GGS disruption;6 wipe with failed recovery;7 slow accumulation;8 opponent faster or follow-up window ended;9 threatening then multiple opponents answered;10 simulator/major AI artifact. Category 9 is evidence of becoming threatening, not equivalent to engine failure. Category 8 does not prove every game was otherwise healthy. Full frequency tables are in the results.']
lines+=['','## Secondary progression and wins','','Rates below are conditional on ignition, except wins. They are descriptive: the baseline and variant can ignite in different games.','','| Removed card | Baseline / variant D2 within 1 turn % | Within 2 turns % | Basic % | Strong % | Threat % | Wins % |','|---|---|---|---|---|---|---|']
for a in arms:
 values=[' / '.join(f(a['contrasts'][k][p+'_percent']) for p in ['baseline','replacement']) for k in ['within_one','within_two','basic_conditional','strong_conditional','threat_conditional','win']]
 lines.append('| '+a['removed']+' | '+' | '.join(values)+' |')
lines+=['','## Observed timing','','| Removed card | Event | Baseline mean / median | Variant mean / median | Baseline / variant observations |','|---|---|---|---|---|']
for a in arms:
 for k,label in [('ggs_cast_turn','GGS cast'),('first_dragon_turn','Dragon #1'),('second_dragon_turn','Dragon #2'),('threat_turn','Threat')]:
  b=a['baseline_timing'][k];v=a['replacement_timing'][k]
  lines.append(f"| {a['removed']} | {label} | {f(b['mean'])} / {f(b['median'])} | {f(v['mean'])} / {f(v['median'])} | {b['n']} / {v['n']} |")
lines+=['','## Stall counts','','Each cell is baseline / variant count. These operational labels are provisional; category 9 records achieved pressure followed by focus, rather than failure to become threatening. Games without a stall label are omitted from this table.','','| Stall category | '+' | '.join(a['removed'] for a in arms)+' |','|---|'+ '|'.join(['---']*len(arms))+'|']
for k in range(1,11):
 values=[str(a['baseline_stalls'].get(str(k),0))+' / '+str(a['replacement_stalls'].get(str(k),0)) for a in arms]
 lines.append('| '+str(k)+' | '+' | '.join(values)+' |')
